const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || {};
const chatId = source.chatId || message.chat?.id || '';
const raw = String(source.rawText || message.text || '').trim();
const query = raw.replace(/^(tim mail|tìm mail|tim email|tìm email|search mail|search email|tim kiem mail|tìm kiếm mail|tim kiem email|tìm kiếm email)\s*/i, '').trim();
const hasQuery = Boolean(query);
const guidance = '🔎 <b>Tìm kiếm email</b>\n\nVí dụ: tìm mail từ Google';
return [{ json: { ...source, chatId, query, hasQuery, response: hasQuery ? '' : guidance } }];

const source = $('Chuan Bi Tim Email').item.json;

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const formatDate = (value) => {
  if (value === undefined || value === null || value === '') return '';
  const normalized = /^\d+$/.test(String(value)) ? Number(value) : value;
  const date = new Date(normalized);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const buildMailLink = (email) => {
  const threadId = pickFirst(email.threadId);
  const messageId = pickFirst(email.id);
  if (threadId) return `https://mail.google.com/mail/u/0/#inbox/${threadId}`;
  if (messageId) return `https://mail.google.com/mail/u/0/#inbox/${messageId}`;
  return '';
};

const rows = $input.all().map((i) => i.json || {}).filter((e) => e.id || e.subject || e.Subject || e.from || e.From || e.snippet);
let text = '🔎 <b>Kết quả tìm email</b>\n\n';
if (!rows.length) {
  text += `Không tìm thấy email phù hợp với: <i>${escapeHtml(source.query)}</i>`;
} else {
  rows.forEach((e, i) => {
    const subject = pickFirst(e.subject, e.Subject, e.payload?.headers?.find((h) => h.name === 'Subject')?.value) || 'Không có tiêu đề';
    const from = pickFirst(e.from?.value?.[0]?.name, e.from?.value?.[0]?.address, e.From, e.from, e.payload?.headers?.find((h) => h.name === 'From')?.value) || 'Không rõ';
    const date = formatDate(pickFirst(e.date, e.Date, e.internalDate));
    const link = buildMailLink(e);
    text += `<b>${i + 1}. ${escapeHtml(subject)}</b>\n👤 ${escapeHtml(from)}\n`;
    if (date) text += `🕒 ${escapeHtml(date)}\n`;
    if (link) text += `🔗 <a href="${escapeHtml(link)}">Link</a>\n`;
    text += '\n';
  });
}
return [{ json: { chatId: source.chatId, text: text.trim() } }];
